#include "tactical.hpp"
#include <algorithm>
namespace transartica::combat {
namespace {int sign(int n){return (n>0)-(n<0);}}
void Tactical::move_trains(){for(int side=0;side<2;++side){if(s_.trains[side][0].health<=0)s_.velocities[side]=0;s_.offsets[side]=std::clamp(s_.offsets[side]+s_.velocities[side],int(s_.trains[side].size())*64-320-center_offset(),s_.columns*16-320-center_offset());}if(s_.ai_wait>0)--s_.ai_wait;else{s_.ai_wait=rnd(100)+20;const int enemy=s_.offsets[1],player=s_.offsets[0];if(enemy-(int(s_.trains[1].size())/2)*64>player||enemy<player-(int(s_.trains[0].size())/2)*64)s_.ai_direction=sign(player-enemy);else if(rnd(3)!=0){if(enemy-int(s_.trains[1].size())*64<s_.columns*16/3)s_.ai_direction=1;else if(enemy>s_.columns*16*2/3)s_.ai_direction=-1;else s_.ai_direction=rnd(3)-1;}else s_.ai_direction=rnd(3)-1;}if(s_.trains[1][0].health>0)s_.velocities[1]+=sign(s_.ai_direction-s_.velocities[1]);}
void Tactical::enemy_ai(){const int index=s_.ai_wagon;s_.ai_wagon=(index+1)%int(s_.trains[1].size());auto&car=s_.trains[1][index];if(car.health<=0)return;switch(car.kind){case Barracks:if(rnd(80)<s_.aggressiveness)deploy(1,index,rnd(30)+1);break;case Livestock:if(rnd(800)<s_.aggressiveness)deploy(1,index,std::min(rnd(62)+1,31));break;case Cannon:if(rnd(800)<s_.aggressiveness&&car.reload==0)car.reload=23;break;case MachineGun:if(rnd(100)<s_.aggressiveness&&car.reload==0){car.reload=13;if(rnd(100)<s_.aggressiveness){const int x=train_cell(1,index),last=6-rnd(2);for(int y=0;y<=last;++y){const auto*a=actor_at(x,y);if(a&&a->side==1){car.reload=0;break;}}}}break;default:break;}}
void Tactical::weapons(){const int first=(s_.offsets[0]-s_.camera_offset)/64;for(int side:{1,0}){const int count=int(s_.trains[side].size());for(int order=0;order<count;++order){const int index=side==1?count-1-order:order;auto&car=s_.trains[side][index];if(car.health<=0||car.reload<=0)continue;if(side==0&&(index<first||index>first+5))continue;const int reload=car.reload;if(car.kind==MachineGun&&reload==12)audio(side==0?0x60ab:0x60b7);else if(car.kind==Cannon&&reload==23){events_.push_back({"cannon",side,index});audio(side==0?0x60c3:0x60cf);}--car.reload;if(car.kind==Cannon&&reload==22)cannon(side,index);else if(car.kind==MachineGun&&reload%2==0)machine_gun(side,index);}}}
void Tactical::cannon(int side,int index){const int opposite=1-side,relative=s_.offsets[opposite]+32-s_.offsets[side]+index*64;if(relative<0||relative>=int(s_.trains[opposite].size())*64)return;const int target=relative/64;auto&car=s_.trains[opposite][target];if(car.health>0){audio(0x60db);--car.health;events_.push_back({"impact",opposite,target});if(opposite==0&&(car.kind==Locomotive||car.kind==Companion))for(auto&linked:s_.trains[0])if(linked.kind==Locomotive||linked.kind==Companion)linked.health=std::min(linked.health,car.health);if(car.health<=0)destroy_wagon(opposite,target);}}
void Tactical::machine_gun(int side,int index){events_.push_back({"machinegun",side,index});const int column=train_cell(side,index),last=side==0?rnd(4):6;for(int order=0;order<7;++order){const int row=side==0?6-order:order;if(side==0&&row<last)break;auto*target=actor(column,row);if(!target)continue;const int before=target->count;if(target->mammoth){if(rnd(3)!=0)target->count=std::max(0,target->count-rnd(3));}else target->count=std::max(0,target->count-rnd(target->side==0?10:7)-1);damage_actor(*target,before);events_.push_back({"shot",-1,-1,target->x,target->y});return;}}
void Tactical::destroy_stock(const Car&car,int side){if(car.kind!=Barracks&&car.kind!=Livestock)return;s_.army_strength[side]-=car.quantity;if(side!=0)return;(car.kind==Barracks?s_.survivors.soldiers:s_.survivors.mammoths)-=car.quantity;}
void Tactical::destroy_wagon(int side,int index){audio(0x60f5);auto&car=s_.trains[side][index];int linked=-1;if(car.kind==Locomotive&&index+1<int(s_.trains[side].size()))linked=index+1;else if(car.kind==Companion&&index>0)linked=index-1;else if(side==1&&car.kind==Tender&&index>0)linked=index-1;if(linked>=0){auto&other=s_.trains[side][linked];destroy_stock(other,side);other.health=other.quantity=other.reload=0;for(auto&[id,a]:s_.actors)if(a.roof==side&&a.x/4==linked){const int before=a.count;a.count=0;damage_actor(a,before);}}destroy_stock(car,side);car.health=car.quantity=car.reload=0;for(auto&[id,a]:s_.actors)if(a.roof==side&&a.x/4==index){const int before=a.count;a.count=0;damage_actor(a,before);}events_.push_back({"destroy",side,index});}
}
